def test_sadness_qp_qpswift(sadness_qp):
    result = qpSWIFT.solve_sparse_H_diag(
        H=sadness_qp.quadratic_weights,
        g=sadness_qp.linear_weights,
        lb=sadness_qp.box_lower_constraints,
        ub=sadness_qp.box_upper_constraints,
        E=sadness_qp.eq_matrix,
        b=sadness_qp.eq_bounds,
        A=sadness_qp.neq_matrix,
        lbA=sadness_qp.neq_lower_bounds,
        ubA=sadness_qp.neq_upper_bounds,
        options=options,
    )
    assert result.exit_flag == 0

def test_well_conditioned_sadness_qp_qpswift(well_conditioned_sadness):
    result = qpSWIFT.solve_sparse_H_diag(
        H=well_conditioned_sadness.quadratic_weights,
        g=well_conditioned_sadness.linear_weights,
        lb=well_conditioned_sadness.box_lower_constraints,
        ub=well_conditioned_sadness.box_upper_constraints,
        E=well_conditioned_sadness.eq_matrix,
        b=well_conditioned_sadness.eq_bounds,
        A=well_conditioned_sadness.neq_matrix,
        lbA=well_conditioned_sadness.neq_lower_bounds,
        ubA=well_conditioned_sadness.neq_upper_bounds,
        options=options,
    )
    print(well_conditioned_sadness.analyze_well_posedness())
    assert result.exit_flag == 0

def solve_and_verify_qp_solution(H, g, lb, ub, E, b, A, lbA, ubA, benchmark: bool = False, precision: float = 1.e-4) -> np.ndarray:
    if len(H.shape) == 2:
        sparse_H = csc_matrix(H)
    else:
        sparse_H = H
        H = np.diag(H)
    sparse_A = csc_matrix(A)
    sparse_E = csc_matrix(E)

    if benchmark:
        iterations = 1000
    else:
        iterations = 1
    t = time.time()
    for i in range(iterations):
        result = qpSWIFT.solve(H, g, lb, ub, E, b, A, lbA, ubA, options)
        assert result.exit_flag == 0
        x_dense = result.x
    print(f'Time(dense): {(time.time() - t)/iterations}')


    t = time.time()
    for i in range(iterations):
        if len(sparse_H.shape) == 1:
            x = qpSWIFT.solve_sparse_H_diag(sparse_H, g, lb, ub, sparse_E, b, sparse_A, lbA, ubA, options).x
        else:
            x = qpSWIFT.solve_sparse(sparse_H, g, lb, ub, sparse_E, b, sparse_A, lbA, ubA, options).x
    print(f'Time(sparse): {(time.time() - t)/iterations}')
    print(f'Solution: {x}')

    if len(sparse_H.shape) == 1:
        x_batch = qpSWIFT.solve_sparse_H_diag_batch(qp_data=[(sparse_H, g, lb, ub, sparse_E, b, sparse_A, lbA, ubA)], options=options)[0].x
        assert np.allclose(x_batch, x), f'batch/sparse: {x_dense} != {x}'

    assert np.allclose(x_dense, x), f'dense/sparse: {x_dense} != {x}'
    # verify eq constraints
    Ex = E.dot(x)
    assert np.allclose(Ex, b), f'Ex: {Ex} == {b}'

    # verify box constraints
    assert np.less_equal(lb, x + precision).all(), f'lb: {lb} <= {x}'
    assert np.less_equal(x, ub + precision).all(), f'ub: {x} <= {ub}'

    # verify ineq constraints
    Ax = A.dot(x)
    assert np.less_equal(lbA, Ax + precision).all(), f'Ax: {lbA} <= {Ax} <= {ubA}'
    assert np.less_equal(Ax, ubA + precision).all(), f'Ax: {lbA} <= {Ax} <= {ubA}'
    return x


def test_infeasibility_check():
    # Simple infeasible QP:
    # min x^2
    # s.t. x >= 1
    #      x <= 0

    H = np.array([[2.0]])
    g = np.array([0.0])

    # x >= 1  => -x <= -1
    # x <= 0
    # qpSWIFT interface for box constraints: lb <= x <= ub
    lb = np.array([1.0])
    ub = np.array([0.0])

    # Options without infeasibility check
    options_no_check = {
        'MAXITER': 10,
        'VERBOSE': 1,
        'CheckInfeasibility': 0
    }

    result = qpSWIFT.solve(H, g, lb, ub, options=options_no_check)
    # Should be QP_MAXIT (2) because it won't converge
    assert result.exit_flag == 2

    # Options with infeasibility check
    options_with_check = {
        'MAXITER': 10,
        'VERBOSE': 1,
        'CheckInfeasibility': 1
    }

    result = qpSWIFT.solve(H, g, lb, ub, options=options_with_check)
    # Should be QP_INFEASIBLE (4)
    assert result.exit_flag == 4


